SELECT

FROM agent_session
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE agent_session
SET stage = #{stage},
    status = #{status},
    turn_count = #{turnCount},
    stage_reask_count = #{stageReaskCount},
    last_active_at = #{lastActiveAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
